package com.tipoff.app;

import android.app.*;
import android.os.*;
import android.graphics.Color;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import android.content.*;
import android.text.InputType;
import android.net.Uri;
import android.util.Xml;
import org.xmlpull.v1.XmlPullParser;
import org.json.*;
import java.net.*;
import java.io.*;
import java.io.StringReader;
import java.util.*;
import java.util.concurrent.*;

public class MainActivity extends Activity {
    final int BG=Color.rgb(10,13,20), CARD=Color.rgb(23,29,40), GREEN=Color.rgb(50,214,139), MUTED=Color.rgb(157,169,187);
    LinearLayout root, body; String page="Home", bdl="", odds="";
    JSONArray games=new JSONArray(), events=new JSONArray();
    ArrayList<JSONObject> news=new ArrayList<>();
    ArrayList<String> legs=new ArrayList<>();
    ArrayList<Double> prices=new ArrayList<>();
    ExecutorService worker=Executors.newSingleThreadExecutor();

    public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);bdl=getPreferences(0).getString("bdl","");odds=getPreferences(0).getString("odds","");restore();show();}
    int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
    TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(5),0,dp(5));return t;}
    LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
    void show(){
        root=column();root.setBackgroundColor(BG);setContentView(root);
        LinearLayout header=new LinearLayout(this);header.setPadding(dp(18),dp(14),dp(18),dp(10));
        TextView brand=text("TIPOFF",26,GREEN);brand.setTypeface(null,1);header.addView(brand);root.addView(header);
        ScrollView scroll=new ScrollView(this);body=column();body.setPadding(dp(16),dp(8),dp(16),dp(20));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        LinearLayout nav=new LinearLayout(this);nav.setBackgroundColor(CARD);
        for(String tab:new String[]{"Home","Games","Scanner","Acca","News","Settings"}){TextView t=text(tab,11,page.equals(tab)?GREEN:MUTED);t.setGravity(Gravity.CENTER);nav.addView(t,new LinearLayout.LayoutParams(0,dp(48),1));t.setOnClickListener(v->{page=tab;show();});}root.addView(nav);
        if(page.equals("Home")){body.addView(text("UK NBA BETTING INTELLIGENCE",12,GREEN));body.addView(text("Make decisions with data.",26,Color.WHITE));card("Live NBA games","Fixtures and scores from BALLDONTLIE. Add your API key in Settings.");button("LOAD NBA GAMES",()->loadGames());button("LOAD UK ODDS",()->loadOdds());card("UK ONLY","Odds are requested with regions=uk and decimal prices. No US odds fallback.");card("HOW ANALYSIS WORKS","Recent-form comparisons use each team's latest completed games. They are descriptive statistics, not guaranteed predictions or proven betting edges.");}
        if(page.equals("Games")){body.addView(text("NBA GAME CENTRE",22,Color.WHITE));button("REFRESH GAMES",()->loadGames());for(int i=0;i<games.length();i++){JSONObject g=games.optJSONObject(i);JSONObject h=g.optJSONObject("home_team"),a=g.optJSONObject("visitor_team");String home=h==null?"Home":h.optString("full_name");String away=a==null?"Away":a.optString("full_name");card(away+" @ "+home,g.optString("date")+"\n"+g.optString("status")+"\n"+g.optString("visitor_team_score")+" - "+g.optString("home_team_score"));int homeId=h==null?0:h.optInt("id");int awayId=a==null?0:a.optInt("id");button("ANALYSE MATCHUP",()->analyseGame(away,awayId,home,homeId));}}
        if(page.equals("Scanner")){body.addView(text("UK MONEYLINE SCANNER",22,Color.WHITE));button("REFRESH UK ODDS",()->loadOdds());for(int i=0;i<events.length();i++){JSONObject e=events.optJSONObject(i);card(e.optString("away_team")+" @ "+e.optString("home_team"),oddsSummary(e));}}
        if(page.equals("Acca")){body.addView(text("ACCUMULATOR BUILDER",22,Color.WHITE));EditText label=input("Selection",false),price=input("Decimal odds (e.g. 1.80)",false);price.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);body.addView(label);body.addView(price);button("ADD LEG",()->{try{double p=Double.parseDouble(price.getText().toString());if(p<=1||label.getText().toString().trim().isEmpty())throw new Exception();legs.add(label.getText().toString().trim());prices.add(p);save();show();}catch(Exception e){toast("Enter a selection and decimal odds greater than 1.");}});for(int i=0;i<legs.size();i++){card(legs.get(i),String.format(Locale.UK,"%.2f",prices.get(i))+" decimal odds");final int index=i;button("REMOVE SELECTION",()->{legs.remove(index);prices.remove(index);save();show();});}if(!legs.isEmpty()){EditText stake=input("Stake in £",false);stake.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);stake.setText("10");body.addView(stake);button("CALCULATE RETURN",()->{try{double s=Double.parseDouble(stake.getText().toString()),o=1;for(double p:prices)o*=p;if(s<=0)throw new Exception();card("POTENTIAL RETURN","£"+String.format(Locale.UK,"%.2f",s*o)+" • Potential profit £"+String.format(Locale.UK,"%.2f",s*(o-1)));}catch(Exception e){toast("Enter a valid stake.");}});button("CLEAR SLIP",()->{legs.clear();prices.clear();save();show();});}}
        if(page.equals("News")){body.addView(text("NBA NEWS",22,Color.WHITE));body.addView(text("Latest headlines from ESPN. Stories open in your browser.",12,MUTED));button("REFRESH NBA NEWS",()->loadNews());if(news.isEmpty())card("NO HEADLINES YET","Tap refresh to load the latest NBA headlines.");for(JSONObject n:news){card(n.optString("title"),n.optString("description"));String link=n.optString("link");if(!link.isEmpty())button("READ STORY",()->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(link)));}catch(Exception e){toast("Could not open story.");}});}}
        if(page.equals("Settings")){body.addView(text("DATA CONNECTIONS",22,Color.WHITE));body.addView(text("BALLDONTLIE API key",14,Color.WHITE));EditText b=input("Paste BALLDONTLIE key",true);b.setText(bdl);body.addView(b);body.addView(text("The Odds API key",14,Color.WHITE));EditText o=input("Paste Odds API key",true);o.setText(odds);body.addView(o);button("SAVE API KEYS",()->{bdl=b.getText().toString().trim();odds=o.getText().toString().trim();getPreferences(0).edit().putString("bdl",bdl).putString("odds",odds).apply();toast("Keys saved on this device.");show();});card("DATA LIMITS","Your provider plan must include UK bookmaker coverage. The app does not guarantee outcomes or provide financial advice. 18+ only.");}
    }
    void analyseGame(String away,int awayId,String home,int homeId){if(bdl.isEmpty()){page="Settings";show();toast("Add your BALLDONTLIE key first.");return;}if(awayId==0||homeId==0){toast("Team information is missing.");return;}page="Analysis";show();card("MATCHUP ANALYSIS",away+" @ "+home+"\nLoading each team's recent completed games…");get("https://api.balldontlie.io/v1/games?per_page=10&team_ids[]="+awayId+"&postseason=false",bdl,"Authorization",a->{get("https://api.balldontlie.io/v1/games?per_page=10&team_ids[]="+homeId+"&postseason=false",bdl,"Authorization",h->{try{JSONObject awayStats=formStats(new JSONObject(a).optJSONArray("data"),awayId);JSONObject homeStats=formStats(new JSONObject(h).optJSONArray("data"),homeId);page="Analysis";show();card("RECENT FORM",away+"\n"+formatStats(awayStats));card("RECENT FORM",home+"\n"+formatStats(homeStats));double aw=awayStats.optDouble("winRate"),hw=homeStats.optDouble("winRate");String edge=hw>aw?home:aw>hw?away:"Neither team";card("FORM COMPARISON",edge+" has the higher win rate across the returned sample. This is a descriptive form comparison, not a calibrated win probability.");card("MODEL LIMITATIONS","This sample does not account for injuries, starting lineups, rest, travel, player availability, pace or matchup strength. Do not treat it as a betting recommendation.");}catch(Exception e){toast("Could not analyse recent form: "+e.getMessage());}});});}
    JSONObject formStats(JSONArray rows,int teamId)throws Exception{int played=0,wins=0,pointsFor=0,pointsAgainst=0;ArrayList<JSONObject> sorted=new ArrayList<>();if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject g=rows.optJSONObject(i);if(g!=null&&!g.optString("status","").toLowerCase(Locale.ROOT).contains("scheduled"))sorted.add(g);}Collections.sort(sorted,(x,y)->x.optString("date").compareTo(y.optString("date")));int start=Math.max(0,sorted.size()-10);for(int i=start;i<sorted.size();i++){JSONObject g=sorted.get(i);int home=g.optInt("home_team_score"),away=g.optInt("visitor_team_score");if(home==0&&away==0)continue;boolean isHome=g.optJSONObject("home_team")!=null&&g.optJSONObject("home_team").optInt("id")==teamId;int pf=isHome?home:away,pa=isHome?away:home;pointsFor+=pf;pointsAgainst+=pa;played++;if(pf>pa)wins++;}JSONObject out=new JSONObject();out.put("played",played);out.put("wins",wins);out.put("losses",played-wins);out.put("winRate",played==0?0:(double)wins/played);out.put("pointsFor",played==0?0:(double)pointsFor/played);out.put("pointsAgainst",played==0?0:(double)pointsAgainst/played);return out;}
    String formatStats(JSONObject s){return s.optInt("wins")+" W - "+s.optInt("losses")+" L from "+s.optInt("played")+" games\nWin rate: "+String.format(Locale.UK,"%.0f%%",s.optDouble("winRate")*100)+"\nAverage points scored: "+String.format(Locale.UK,"%.1f",s.optDouble("pointsFor"))+"\nAverage points conceded: "+String.format(Locale.UK,"%.1f",s.optDouble("pointsAgainst"));}
    void card(String title,String value){LinearLayout c=column();GradientDrawable bg=new GradientDrawable();bg.setColor(CARD);bg.setCornerRadius(dp(14));c.setBackground(bg);c.setPadding(dp(15),dp(13),dp(15),dp(13));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(11);body.addView(c,p);TextView h=text(title,14,GREEN);h.setTypeface(null,1);c.addView(h);TextView v=text(value,13,Color.rgb(220,226,235));v.setLineSpacing(dp(2),1f);c.addView(v);}
    void button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextSize(13);b.setTypeface(null,1);b.setTextColor(Color.rgb(8,18,16));GradientDrawable bg=new GradientDrawable();bg.setColor(GREEN);bg.setCornerRadius(dp(11));b.setBackground(bg);b.setPadding(dp(12),dp(7),dp(12),dp(7));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(8);b.setLayoutParams(p);b.setOnClickListener(v->action.run());body.addView(b);}
    EditText input(String hint,boolean secret){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);e.setTextColor(Color.WHITE);e.setHintTextColor(MUTED);if(secret)e.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);return e;}
    void loadGames(){if(bdl.isEmpty()){page="Settings";show();toast("Add your BALLDONTLIE key first.");return;}get("https://api.balldontlie.io/v1/games?per_page=25",bdl,"Authorization",s->{try{games=new JSONObject(s).optJSONArray("data");if(games==null)games=new JSONArray();page="Games";show();}catch(Exception e){toast(s);}});}
    void loadNews(){get("https://www.espn.com/espn/rss/nba/news","","",xml->{try{news=parseNews(xml);page="News";show();if(news.isEmpty())toast("No NBA headlines were returned.");}catch(Exception e){toast("Could not read NBA news: "+e.getMessage());}});}
    ArrayList<JSONObject> parseNews(String xml)throws Exception{ArrayList<JSONObject> items=new ArrayList<>();XmlPullParser p=Xml.newPullParser();p.setInput(new StringReader(xml));int event=p.getEventType();JSONObject current=null;String field="";while(event!=XmlPullParser.END_DOCUMENT){if(event==XmlPullParser.START_TAG){String tag=p.getName();if("item".equals(tag))current=new JSONObject();else if(current!=null&&("title".equals(tag)||"description".equals(tag)||"link".equals(tag)))field=tag;}else if(event==XmlPullParser.TEXT&&current!=null&&!field.isEmpty()){String value=p.getText();current.put(field,current.optString(field)+value);}else if(event==XmlPullParser.END_TAG){String tag=p.getName();if("item".equals(tag)&&current!=null){items.add(current);current=null;}if(tag.equals(field))field="";}event=p.next();}return items;}
    void loadOdds(){if(odds.isEmpty()){page="Settings";show();toast("Add your Odds API key first.");return;}get("https://api.the-odds-api.com/v4/sports/basketball_nba/odds/?regions=uk&markets=h2h&oddsFormat=decimal&apiKey="+Uri.encode(odds),"","",s->{try{events=new JSONArray(s);page="Scanner";show();if(events.length()==0)toast("No UK odds returned. Check plan coverage.");}catch(Exception e){toast("UK odds unavailable: "+s);}});}
    String oddsSummary(JSONObject e){StringBuilder out=new StringBuilder("BEST UK PRICE • DECIMAL\n");JSONArray books=e.optJSONArray("bookmakers");if(books==null)return out.append("No prices available").toString();LinkedHashMap<String,Double> best=new LinkedHashMap<>();LinkedHashMap<String,String> shops=new LinkedHashMap<>();for(int i=0;i<books.length();i++){JSONObject b=books.optJSONObject(i);JSONArray markets=b.optJSONArray("markets");if(markets==null)continue;for(int j=0;j<markets.length();j++){JSONObject market=markets.optJSONObject(j);if(market==null||!"h2h".equals(market.optString("key")))continue;JSONArray outcomes=market.optJSONArray("outcomes");if(outcomes==null)continue;for(int k=0;k<outcomes.length();k++){JSONObject x=outcomes.optJSONObject(k);String name=x.optString("name");double price=x.optDouble("price",0);if(price>1&&(!best.containsKey(name)||price>best.get(name))){best.put(name,price);shops.put(name,b.optString("title"));}}}}if(best.isEmpty())return out.append("No UK bookmaker prices returned.").toString();for(String name:best.keySet()){double price=best.get(name);out.append("\n").append(name).append("\n").append(String.format(Locale.UK,"%.2f",price)).append("  •  ").append(shops.get(name)).append("\n");}out.append("\nBest displayed price only; not a value-bet rating.");String time=e.optString("commence_time");if(!time.isEmpty())out.append("\nStart: ").append(time);return out.toString();}
    interface Done{void result(String s);}
    void get(String url,String key,String header,Done done){worker.execute(()->{String result;HttpURLConnection c=null;try{c=(HttpURLConnection)new URL(url).openConnection();if(!key.isEmpty())c.setRequestProperty(header,key);c.setConnectTimeout(15000);c.setReadTimeout(20000);int code=c.getResponseCode();InputStream in=code<400?c.getInputStream():c.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);result=out.toString("UTF-8");if(code>=400)result="HTTP "+code+": "+result;}catch(Exception e){result="Network error: "+e.getMessage();}finally{if(c!=null)c.disconnect();}String r=result;runOnUiThread(()->done.result(r));});}
    void save(){JSONArray a=new JSONArray();try{for(int i=0;i<legs.size();i++){JSONObject x=new JSONObject();x.put("label",legs.get(i));x.put("odds",prices.get(i));a.put(x);}}catch(Exception ignored){}getPreferences(0).edit().putString("acca",a.toString()).apply();}
    void restore(){try{JSONArray a=new JSONArray(getPreferences(0).getString("acca","[]"));for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);legs.add(x.optString("label"));prices.add(x.optDouble("odds"));}}catch(Exception ignored){}}
    void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    @Override protected void onDestroy(){super.onDestroy();worker.shutdownNow();}
}